import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.FZrpoovI.js";const p=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1778061865000}'),i={name:"guide/introduction.md"};function d(l,e,n,h,c,s){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><hr><p><code>Taro UI</code> 是一款基于 <a href="https://taro.jd.com/" target="_blank" rel="noreferrer">Taro</a> 框架开发的多端 UI 组件库</p><h2 id="taro" tabindex="-1">Taro <a class="header-anchor" href="#taro" aria-label="Permalink to &quot;Taro&quot;">​</a></h2><p>Taro 是由 <a href="https://aotu.io" target="_blank" rel="noreferrer">京东·凹凸实验室</a> 倾力打造的多端开发解决方案。现如今市面上端的形态多种多样，Web、ReactNative、微信小程序等各种端大行其道，当业务要求同时在不同的端都要求有所表现的时候，针对不同的端去编写多套代码的成本显然非常高，这时候只编写一套代码就能够适配到多端的能力就显得极为需要。</p><p>使用 Taro，我们可以只书写一套代码，再通过 Taro 的编译工具，将源代码分别编译出可以在不同端（微信小程序、H5、RN等）运行的代码。</p><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>基于 <code>Taro</code> 开发 UI 组件</li><li>一套组件可以在 <code>微信小程序</code>，<code>支付宝小程序</code>，<code>百度小程序</code>，<code>H5</code> 、<code>ReactNative</code> 等多端适配运行</li><li>提供友好的 API，可灵活的使用组件</li></ul><h2 id="体验" tabindex="-1">体验 <a class="header-anchor" href="#体验" aria-label="Permalink to &quot;体验&quot;">​</a></h2><p>使用微信扫一扫体验 <code>小程序</code> 和 <code>H5</code> 组件示例</p><p><img src="https://user-images.githubusercontent.com/1240899/46650700-25a4e600-cbd0-11e8-90ff-905edb39c340.jpg" alt="QRCode"></p><h2 id="官方示例" tabindex="-1">官方示例 <a class="header-anchor" href="#官方示例" aria-label="Permalink to &quot;官方示例&quot;">​</a></h2><p><a href="https://github.com/NervJS/taro-ui-demo" target="_blank" rel="noreferrer">Taro UI 官方示例</a></p><h2 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h2><p><code>Taro-UI</code>：<a href="https://badge.fury.io/js/taro-ui" target="_blank" rel="noreferrer"><img src="https://badge.fury.io/js/taro-ui.svg" alt="npm version"></a></p><h2 id="开发交流" tabindex="-1">开发交流 <a class="header-anchor" href="#开发交流" aria-label="Permalink to &quot;开发交流&quot;">​</a></h2><p><a href="https://github.com/NervJS/taro-ui/issues/16" target="_blank" rel="noreferrer">官方微信交流群</a></p><h2 id="开发计划" tabindex="-1">开发计划 <a class="header-anchor" href="#开发计划" aria-label="Permalink to &quot;开发计划&quot;">​</a></h2><p><a href="https://github.com/NervJS/taro-ui/blob/dev/PLANS.md" target="_blank" rel="noreferrer">Taro UI 开发计划</a></p><h2 id="贡献" tabindex="-1">贡献 <a class="header-anchor" href="#贡献" aria-label="Permalink to &quot;贡献&quot;">​</a></h2><p>如果你在使用 <code>Taro UI</code> 时遇到问题，或者有好的建议，欢迎给我们提 <a href="https://github.com/nervjs/taro-ui/issues" target="_blank" rel="noreferrer">Issue</a> 或 <a href="https://github.com/nervjs/taro-ui/pulls" target="_blank" rel="noreferrer">Pull Request</a></p>',21)])])}const b=a(i,[["render",d]]);export{p as __pageData,b as default};
